#!/usr/bin/env bash
# SCRIPT_JDOC: {"summary":"Compare deployed and semantic-parity Gemma zero-copy binaries with attached pools disabled","kind":"mixed","weight":"heavy","role":"entrypoint"}
set -euo pipefail
root=$(cd "$(dirname "$0")/../../.." && pwd)
out="$root/benchmarks/intel-1340p/gemma-generation-parity-20260916/semantic-candidate-ab"
live="$root/build-gemma-zero-copy-vulkan"
candidate="$root/build-gemma-generation-parity"
runtime="$root/runtime/gemma-vulkan-f32-0bdd7cd8b/runtime"
model="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B_q4_0-it.gguf"
draft="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B-it-qat-assistant-MTP-Q8_0.gguf"
fixture="$root/benchmarks/intel-1340p/gemma-generation-parity-20260916/fixtures/sustained-chat-512.json"
production=llama-gemma-zero-copy.service
mkdir -p "$out/runs"
export XDG_RUNTIME_DIR=/run/user/$(id -u); export DBUS_SESSION_BUS_ADDRESS=unix:path=$XDG_RUNTIME_DIR/bus
restore(){ local rc=$?; for u in $(systemctl --user list-units --all --plain --no-legend 'gemma-parity-semantic-ab-*.service' 2>/dev/null|awk '{print $1}');do systemctl --user stop "$u">/dev/null 2>&1||true;systemctl --user reset-failed "$u">/dev/null 2>&1||true;done; systemctl --user start "$production">/dev/null 2>&1||true; local ok=0;for _ in $(seq 1 180);do if curl -fsS http://127.0.0.1:18094/health>"$out/restored-health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;systemctl --user show "$production" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemorySwapCurrent -p MemorySwapPeak>"$out/restored-service.txt" 2>&1||true;[[ $ok == 1 ]]||rc=1;exit "$rc";};trap restore EXIT INT TERM
systemctl --user is-active --quiet "$production";[[ $(systemctl --user show whisper-stt.service -p ActiveState --value) == inactive ]];[[ $(systemctl --user show whisper-stt-diarizer.service -p ActiveState --value) == inactive ]];! pgrep -x diar-server>/dev/null;! pgrep -x whisper-cli>/dev/null;[[ $(awk '/MemAvailable:/{print $2}' /proc/meminfo) -ge 12582912 ]];systemctl --user stop "$production"
[[ -s "$out/results.tsv" ]]||printf 'sequence\tarm\tdecode_tps\twall_s\tprefill_s\tdrafted\taccepted\tgenerated\tmemory_peak\tswap_peak\tcontent_sha256\n'>"$out/results.tsv"
run_one(){ local seq=$1 arm=$2;local port=$((18700+seq));local unit="gemma-parity-semantic-ab-${seq}.service";local dir="$out/runs/$(printf '%02d-%s' "$seq" "$arm")";if [[ -e $dir/complete ]];then awk -F '\t' -v s="$seq" 'NR>1&&$1==s{f=1}END{exit !f}' "$out/results.tsv";return;fi;[[ ! -e $dir ]];mkdir -p "$dir";local build=$live;local extra=();if [[ $arm == candidate ]];then build=$candidate;extra=(--draft-min 1 --threadpools 0 --model-sampling 1);fi
systemd-run --user --unit "$unit" --collect -p Type=simple -p TimeoutStopSec=30 -p MemoryMax=16G -p MemorySwapMax=0 -p TasksMax=256 --setenv=LD_LIBRARY_PATH="$build/bin:$runtime" --setenv=GGML_VK_VISIBLE_DEVICES=0 --setenv=GGML_VK_EXPERIMENTAL_ATTN_MODE=f32 "$build/bin/llama-gemma-zero-copy-server" --model "$model" --draft "$draft" --alias "gemma-semantic-ab-$arm" --host 127.0.0.1 --port "$port" --ctx-size 32768 --batch-size 256 --ubatch-size 256 --threads 8 --threads-batch 16 --draft-max 3 "${extra[@]}" --max-output 2048 > "$dir/systemd-run.txt";local ok=0;for _ in $(seq 1 180);do if curl -fsS "http://127.0.0.1:$port/health">"$dir/health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;[[ $ok == 1 ]];curl -fsS "http://127.0.0.1:$port/props">"$dir/props.json";curl --max-time 180 -fsS "http://127.0.0.1:$port/v1/chat/completions" -H 'Content-Type: application/json' -H "X-Conversation-Id: semantic-ab-$seq" --data-binary @"$fixture">"$dir/response.json";jq -e '.usage.completion_tokens==512 and .choices[0].finish_reason=="length" and .zero_copy.shared_bytes>0 and .zero_copy.copied_bytes==0 and .zero_copy.zero_copy==true' "$dir/response.json";jq -r '.choices[0].message.content' "$dir/response.json"|sha256sum|cut -d' ' -f1>"$dir/content-sha256.txt";systemctl --user show "$unit" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemoryCurrent -p MemoryPeak -p MemorySwapCurrent -p MemorySwapPeak>"$dir/service.txt";local swap=$(sed -n 's/^MemorySwapPeak=//p' "$dir/service.txt");[[ $swap == 0 ]];local mem=$(sed -n 's/^MemoryPeak=//p' "$dir/service.txt");local dec=$(jq -r '.zero_copy.decode_tps' "$dir/response.json");local wall=$(jq -r '.zero_copy.wall_s' "$dir/response.json");local pre=$(jq -r '.zero_copy.prefill_s' "$dir/response.json");local drafted=$(jq -r '.zero_copy.drafted' "$dir/response.json");local accepted=$(jq -r '.zero_copy.accepted' "$dir/response.json");local gen=$(jq -r '.zero_copy.generated_tokens' "$dir/response.json");local hash=$(cat "$dir/content-sha256.txt");printf '%d\t%s\t%.9f\t%.9f\t%.9f\t%d\t%d\t%d\t%s\t%s\t%s\n' "$seq" "$arm" "$dec" "$wall" "$pre" "$drafted" "$accepted" "$gen" "$mem" "$swap" "$hash">>"$out/results.tsv";journalctl --user -u "$unit" --no-pager>"$dir/journal.txt";sha256sum "$dir"/* >"$dir/SHA256SUMS";touch "$dir/complete";systemctl --user stop "$unit";systemctl --user reset-failed "$unit">/dev/null 2>&1||true;sleep 2;}
run_one 1 live;run_one 2 candidate;run_one 3 candidate;run_one 4 live;sha256sum "$out/results.tsv">"$out/SHA256SUMS"
